recent_command_receipts.command:
cd /app && echo 'CSV_PREVIEW' && sed -n '1,20p' summary.csv && echo 'VERIFY' && awk '
function add(period, sev){c[period,sev]++}
function in_range(d, s, e){return (d>=s && d<=e)}
BEGIN{FS="[[:space:]]+|\[|\]"}
FNR==1{file=FILENAME; date=substr(file,6,10)}
{
  sev=""
  for(i=1;i<=NF;i++) if($i=="ERROR" || $i=="WARNING" || $i=="INFO") {sev=$i; break}
  if(sev=="") next
  add("total", sev)
  if(in_range(date, "2025-08-12", "2025-08-12")) add("today", sev)
  if(in_range(date, "2025-08-06", "2025-08-12")) add("last_7_days", sev)
  if(in_range(date, "2025-07-14", "2025-08-12")) add("last_30_days", sev)
  if(in_range(date, "2025-08-01", "2025-08-12")) add("month_to_date", sev)
}
END{
  for(p=1;p<=5;p++){
    period=(p==1?"today":p==2?"last_7_days":p==3?"last_30_days":p==4?"month_to_date":"total")
    for(s=1;s<=3;s++){
      sev=(s==1?"ERROR":s==2?"WARNING":"INFO")
      print period, sev, c[period,sev]+0
    }
  }
}' logs/*.log | sed 's/ /,/g'
